  1	/**
  2	 * Repositories View — Repo Parallelizer GUI.
  3	 *
  4	 * Renders a full CRUD management page for all registered repositories:
  5	 *   - Table listing all repositories (ID, Name, URL).
  6	 *   - "Add Repository" inline form (URL required, Name optional, ID optional).
  7	 *   - Inline edit for repository Name per row.
  8	 *   - Delete per row with a confirmation dialog.
  9	 *
 10	 * @param {HTMLElement} container - The `#app` root element supplied by the router.
 11	 * @param {Object}      _params   - Route params (none for this route).
 12	 */
 13	
 14	import { api } from '../api.js';
 15	import { showToast } from '../components/toast.js';
 16	import { showConfirm } from '../components/confirm-dialog.js';
 17	import { createFormField, validateRequired } from '../components/form-helpers.js';
 18	import { normaliseRepo } from '../utils/normalise.js';
 19	
 20	// ---------------------------------------------------------------------------
 21	// Table rendering
 22	// ---------------------------------------------------------------------------
 23	
 24	/**
 25	 * Build the `<thead>` element for the repository table.
 26	 *
 27	 * @returns {HTMLElement}
 28	 */
 29	function buildTableHead() {
 30	    const thead = document.createElement('thead');
 31	    const tr    = document.createElement('tr');
 32	
 33	    ['ID', 'Name', 'URL', 'Actions'].forEach((label) => {
 34	        const th = document.createElement('th');
 35	        th.textContent = label;
 36	        tr.appendChild(th);
 37	    });
 38	
 39	    thead.appendChild(tr);
 40	    return thead;
 41	}
 42	
 43	/**
 44	 * Build a single `<tr>` for one repository.
 45	 *
 46	 * The row starts in read mode.  The Name cell renders as a clickable `<a>`
 47	 * link navigating to `#/repositories/:id`.  Clicking Edit switches the Name
 48	 * cell to an inline `<input>` and replaces the action buttons with Save / Cancel.
 49	 * Clicking Delete shows a confirmation dialog and calls the API on confirm.
 50	 *
 51	 * @param {{ id: string, name: string, url: string }} repo
 52	 * @param {function(): void} onDeleted - Callback to refresh the table after deletion.
 53	 * @returns {HTMLTableRowElement}
 54	 */
 55	function buildRepoRow(repo, onDeleted) {
 56	    const tr = document.createElement('tr');
 57	    tr.dataset.repoId = repo.id;
 58	
 59	    // ---- ID cell (read-only) ----
 60	    const idCell = document.createElement('td');
 61	    idCell.className = 'repo-id-cell text-muted';
 62	    idCell.textContent = repo.id;
 63	    tr.appendChild(idCell);
 64	
 65	    // ---- Name cell (editable) ----
 66	    const nameCell = document.createElement('td');
 67	    nameCell.className = 'repo-name-cell';
 68	
 69	    const nameLink = document.createElement('a');
 70	    nameLink.className = 'repo-name-display repo-name-link';
 71	    nameLink.href      = `#/repositories/${encodeURIComponent(repo.id)}`;
 72	    nameLink.textContent = repo.name || '—';
 73	    nameCell.appendChild(nameLink);
 74	
 75	    // Inline edit input (hidden initially)
 76	    const nameInput = document.createElement('input');
 77	    nameInput.type       = 'text';
 78	    nameInput.className  = 'form-input repo-name-input';
 79	    nameInput.value      = repo.name;
 80	    nameInput.hidden     = true;
 81	    nameInput.setAttribute('aria-label', `Name for repository ${repo.id}`);
 82	    nameCell.appendChild(nameInput);
 83	
 84	    tr.appendChild(nameCell);
 85	
 86	    // ---- URL cell (read-only) ----
 87	    const urlCell = document.createElement('td');
 88	    urlCell.className = 'repo-url-cell';
 89	    const urlLink = document.createElement('a');
 90	    urlLink.href      = repo.url;
 91	    urlLink.textContent = repo.url;
 92	    urlLink.target    = '_blank';
 93	    urlLink.rel       = 'noopener noreferrer';
 94	    urlLink.className = 'repo-url-link';
 95	    urlCell.appendChild(urlLink);
 96	    tr.appendChild(urlCell);
 97	
 98	    // ---- Actions cell ----
 99	    const actionsCell = document.createElement('td');
100	    actionsCell.className = 'repo-actions-cell';

101	
102	    // Read-mode buttons
103	    const editBtn = document.createElement('button');
104	    editBtn.type      = 'button';
105	    editBtn.className = 'btn btn-secondary btn-sm';
106	    editBtn.textContent = 'Edit';
107	
108	    const deleteBtn = document.createElement('button');
109	    deleteBtn.type      = 'button';
110	    deleteBtn.className = 'btn btn-danger btn-sm';
111	    deleteBtn.textContent = 'Delete';
112	
113	    // Edit-mode buttons (hidden initially)
114	    const saveBtn = document.createElement('button');
115	    saveBtn.type      = 'button';
116	    saveBtn.className = 'btn btn-primary btn-sm';
117	    saveBtn.textContent = 'Save';
118	    saveBtn.hidden    = true;
119	
120	    const cancelEditBtn = document.createElement('button');
121	    cancelEditBtn.type      = 'button';
122	    cancelEditBtn.className = 'btn btn-secondary btn-sm';
123	    cancelEditBtn.textContent = 'Cancel';
124	    cancelEditBtn.hidden    = true;
125	
126	    actionsCell.appendChild(editBtn);
127	    actionsCell.appendChild(deleteBtn);
128	    actionsCell.appendChild(saveBtn);
129	    actionsCell.appendChild(cancelEditBtn);
130	    tr.appendChild(actionsCell);
131	
132	    // -------------------------------------------------------------------------
133	    // Behaviour
134	    // -------------------------------------------------------------------------
135	
136	    // Enter edit mode
137	    editBtn.addEventListener('click', () => {
138	        nameLink.hidden  = true;
139	        nameInput.hidden = false;
140	        nameInput.value  = repo.name;
141	        nameInput.focus();
142	        nameInput.select();
143	
144	        editBtn.hidden   = true;
145	        deleteBtn.hidden = true;
146	        saveBtn.hidden   = false;
147	        cancelEditBtn.hidden = false;
148	    });
149	
150	    // Cancel edit mode
151	    cancelEditBtn.addEventListener('click', () => {
152	        nameInput.hidden = true;
153	        nameLink.hidden  = false;
154	
155	        editBtn.hidden   = false;
156	        deleteBtn.hidden = false;
157	        saveBtn.hidden   = true;
158	        cancelEditBtn.hidden = true;
159	    });
160	
161	    // Save name change
162	    saveBtn.addEventListener('click', async () => {
163	        const newName = nameInput.value.trim();
164	        saveBtn.disabled = true;
165	        saveBtn.textContent = 'Saving…';
166	
167	        try {
168	            await api.repositories.update(repo.id, { name: newName });
169	            repo.name = newName;
170	            nameLink.textContent = newName || '—';
171	            showToast(`Repository "${repo.id}" updated.`, 'success');
172	
173	            // Return to read mode
174	            nameInput.hidden = true;
175	            nameLink.hidden  = false;
176	            editBtn.hidden   = false;
177	            deleteBtn.hidden = false;
178	            saveBtn.hidden   = true;
179	            cancelEditBtn.hidden = true;
180	        } catch (err) {
181	            showToast(err.message || 'Failed to update repository.', 'error');
182	        } finally {
183	            saveBtn.disabled = false;
184	            saveBtn.textContent = 'Save';
185	        }
186	    });
187	
188	    // Allow pressing Enter in the name input to save
189	    nameInput.addEventListener('keydown', (e) => {
190	        if (e.key === 'Enter') {
191	            e.preventDefault();
192	            saveBtn.click();
193	        } else if (e.key === 'Escape') {
194	            cancelEditBtn.click();
195	        }
196	    });
197	
198	    // Delete with confirmation
199	    deleteBtn.addEventListener('click', async () => {
200	        try {
201	            await showConfirm(
202	                'Delete Repository',
203	                `Delete "${repo.name || repo.id}"? This repository will be removed from all projects. This action cannot be undone.`,
204	            );
205	        } catch {
206	            // User cancelled — do nothing.
207	            return;
208	        }
209	
210	        deleteBtn.disabled = true;
211	        deleteBtn.textContent = 'Deleting…';
212	
213	        try {
214	            await api.repositories.delete(repo.id);
215	            showToast(`Repository "${repo.name || repo.id}" deleted.`, 'success');
216	            onDeleted();
217	        } catch (err) {
218	            showToast(err.message || 'Failed to delete repository.', 'error');
219	            deleteBtn.disabled = false;
220	            deleteBtn.textContent = 'Delete';
221	        }
222	    });
223	
224	    return tr;
225	}
226	
227	// ---------------------------------------------------------------------------
228	// Repository list rendering
229	// ---------------------------------------------------------------------------
230	
231	/**
232	 * Render a loading indicator into `tableContainer`.
233	 *
234	 * @param {HTMLElement} tableContainer
235	 */
236	function showLoading(tableContainer) {
237	    tableContainer.innerHTML = `
238	        <div class="loading-indicator" aria-live="polite" aria-label="Loading repositories…">
239	            <span class="spinner" aria-hidden="true"></span>
240	            <span>Loading repositories…</span>
241	        </div>
242	    `;
243	}
244	
245	/**
246	 * Fetch all repositories and render them into `tableContainer`.
247	 * On success renders a `<table>`; on failure shows an error state.
248	 *
249	 * @param {HTMLElement} tableContainer - Element to render the table into.
250	 */
251	async function renderRepoTable(tableContainer) {
252	    showLoading(tableContainer);
253	
254	    let repos;
255	    try {
256	        repos = await api.repositories.list();
257	    } catch (err) {
258	        tableContainer.innerHTML = '';
259	        const errMsg = document.createElement('div');
260	        errMsg.className = 'empty-state error-state';
261	        errMsg.textContent = `Failed to load repositories: ${err.message}`;
262	        tableContainer.appendChild(errMsg);
263	        showToast(err.message || 'Failed to load repositories.', 'error');
264	        return;
265	    }
266	
267	    tableContainer.innerHTML = '';
268	
269	    if (!Array.isArray(repos) || repos.length === 0) {
270	        const empty = document.createElement('div');
271	        empty.className = 'empty-state';
272	        empty.textContent = 'No repositories registered. Use the "Add Repository" button to add one.';
273	        tableContainer.appendChild(empty);
274	        return;
275	    }
276	
277	    const table = document.createElement('table');
278	    table.className = 'data-table repositories-table';
279	    table.appendChild(buildTableHead());
280	
281	    const tbody = document.createElement('tbody');
282	    repos.forEach((raw) => {
283	        const repo = normaliseRepo(raw);
284	        tbody.appendChild(buildRepoRow(repo, () => renderRepoTable(tableContainer)));
285	    });
286	
287	    table.appendChild(tbody);
288	    tableContainer.appendChild(table);
289	}
290	
291	// ---------------------------------------------------------------------------
292	// Add Repository form
293	// ---------------------------------------------------------------------------
294	
295	/**
296	 * Build and return the "Add Repository" inline form section.
297	 * On success, `onSuccess` is called so the caller can re-render the table.
298	 *
299	 * @param {function(): void} onSuccess
300	 * @returns {HTMLElement}

  1	/**
  2	 * Unit tests for views/repositories.js — WP-004.
  3	 *
  4	 * Acceptance Criteria verified:
  5	 *   AC1  — Each repository's Name column renders as a clickable <a> element.
  6	 *   AC2  — Clicking a repository name navigates to #/repositories/:id
  7	 *           (where :id is the repository's encoded ID).
  8	 *   AC3  — The inline edit (Edit/Save/Cancel) behaviour on the Name cell
  9	 *           continues to work correctly after the span→link refactor.
 10	 *
 11	 * Uses Node's built-in test runner with jsdom for a minimal DOM environment.
 12	 * Run individually with:
 13	 *   node --test gui/public/js/views/repositories.test.mjs
