205	test('AC3 — Cancelling edit restores the name link', async () => {
206	    const container = await renderAndWait();
207	    try {
208	        const nameCell     = container.querySelector('td.repo-name-cell');
209	        const nameLink     = nameCell.querySelector('a.repo-name-display');
210	        const nameInput    = nameCell.querySelector('input.repo-name-input');
