157	            this._container.innerHTML = '';
158	            const msg = document.createElement('div');
159	            msg.className = 'empty-state';
160	            msg.textContent = `Page not found: ${hash}`;
161	            this._container.appendChild(msg);
162	        }
163	    }
164	
